alter table public.sm_products add column if not exists length_text text;
alter table public.sm_products add column if not exists width_text text;
alter table public.sm_products add column if not exists height_text text;
delete from public.sm_products where name_ar like 'تجهيز غرفة ألعاب - نموذج %' or name_ar like 'تجهيز صالة ألعاب - نموذج %' or name_ar like 'تجهيز صالة ألعاب - تصميم %';
update public.sm_pages set body_ar='مؤسسة صُنّاع عالم البسمه للترفيه، رائدة في تصميم وتجهيز مراكز الترفيه والألعاب الحركية للأطفال بالمنازل والمدارس ورياض الأطفال أيضاً..
بخبرة تتجاوز 10 سنوات في تقديم حلول ترفيهية متكاملة ومبتكرة.

نحوّل الأفكار إلى مشاريع ترفيهية متميزة، بدءًا من التخطيط والتصميم، وصولًا إلى التجهيز والتركيب والتسليم، مع الالتزام بأعلى معايير الجودة والسلامة والابتكار.', body_en='Smile Makers Entertainment is a specialist in designing and equipping entertainment centres and active-play spaces for children in homes, schools and kindergartens, with more than 10 years of experience delivering integrated and innovative entertainment solutions. We turn ideas into distinctive entertainment projects, from planning and design through equipment, installation and handover, with a commitment to quality, safety and innovation.', image='' where slug='about';
